// <diletta-web-top-bar> — a INSTÂNCIA WEB de `design-system-web-top-bar`.
//
// Não é o `DilettaTopAppBar`: aquele tem 52, é de celular e empurra o relógio do
// sistema. Esta tem 72 ou 104, mora numa janela e não conhece safe area.
const ALTURA = { autenticada: 72, anonima: 104 };

class DilettaWebTopBar extends HTMLElement {
  static observedAttributes = ['sessao', 'nome', 'papel', 'href'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  get sessao() {
    return this.getAttribute('sessao') === 'anonima' ? 'anonima' : 'autenticada';
  }

  render() {
    const s = this.sessao;
    const nome = this.getAttribute('nome') || '';
    const papel = this.getAttribute('papel') || '';

    // A barra ANÔNIMA é a MAIS ALTA — 104 contra 72 — e é intencional: sem avatar
    // nem nome para ancorar a direita, a marca ganha respiro. Quem implementar não
    // deve "corrigir" para 72 achando que é desalinho.
    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        .barra {
          box-sizing: border-box; height: ${ALTURA[s]}px;
          display: flex; align-items: center; gap: 16px; padding: 0 24px;
          /* A barra é bg, o tom da TELA — não surface. Medido: 71px de #f8faff e
             1px de #ececec em y=71, e o painel de conteúdo branco só a partir de
             y=72. O que separa a casca do conteúdo é régua de borderSubtle. */
          background: var(--cps-bg);
          border-width: 0 0 1px; border-style: solid; border-color: var(--cps-borderSubtle);
        }
        /* A marca é ALVO: leva à raiz. Marca que não é alvo obriga a pessoa a
           procurar a trilha. */
        .marca { display: inline-flex; align-items: center; min-height: 44px;
                 margin-inline-end: auto; color: inherit; }
        .marca:focus-visible { outline: 3px solid var(--cps-primary); outline-offset: 2px; }
        /* A direita é uma FILA de atalhos, não posições nomeadas: slot nomeado por
           atalho obrigaria variante nova a cada um — e o Entity deste conjunto já
           mostra o custo disso, com um valor por PRODUTO (IB, Webadmin, logged in/out).
           Sem crase aqui: este comentário mora DENTRO do template literal do CSS. */
        .fila { display: flex; align-items: center; gap: 8px; }
        .quem { display: flex; flex-direction: column; align-items: flex-end; line-height: 1.2; }
        .nome { color: var(--cps-fg); }
        .papel { color: var(--cps-textSecondary); font-size: var(--cps-type-caption-size, 12px); }
      </style>
      <header class="barra" part="barra" role="banner">
        <a class="marca" href="${(this.getAttribute('href') || '/').replace(/"/g, '&quot;')}"
           aria-label="Início"><slot name="marca"></slot></a>
        <div class="fila"><slot name="atalhos"></slot>
          ${s === 'autenticada' && nome
            ? `<span class="quem"><span class="nome">${nome}</span>${papel ? `<span class="papel">${papel}</span>` : ''}</span><slot name="avatar"></slot>`
            : ''}
        </div>
      </header>`;
  }
}

customElements.define('diletta-web-top-bar', DilettaWebTopBar);
export { DilettaWebTopBar, ALTURA };
